let cwnd = 12000;          // bytes
const sent = new Map();     // pktNum -> { sentAt, frames, isRetransmit }

function onSend(pktNum, frames, isRetransmit) {
  sent.set(pktNum, { sentAt: now(), frames, isRetransmit });
}

function onAck(pktNum) {
  const p = sent.get(pktNum);
  if (!p) return;
  // Always update RTT from the elapsed time of this packet.
  updateRtt(now() - p.sentAt);
  sent.delete(pktNum);
}

function onLoss(pktNum) {
  // Any loss means congestion: halve the window.
  cwnd = cwnd / 2;
}
